/**
 * Opening a link in a new tab, reliably — including on iPad.
 *
 * `window.open()` is only honoured while the browser considers a user gesture
 * to be in progress. iOS/iPadOS Safari is the strictest about this: a call made
 * from a `pointerdown` handler (which is what the desktop icons and the Start
 * menu use) is frequently treated as programmatic and silently swallowed by the
 * popup blocker, so the tap appears to do nothing at all.
 *
 * Clicking a real anchor element is never blocked, so we try `window.open`
 * first (keeps desktop behaviour identical) and fall back to a synthetic anchor
 * when it's refused.
 */
export function openExternal(url: string): void {
    let win: Window | null = null;
    try {
        win = window.open(url, '_blank', 'noopener,noreferrer');
    } catch {
        win = null;
    }
    if (win) return;

    const a = document.createElement('a');
    a.href = url;
    a.target = '_blank';
    a.rel = 'noopener noreferrer';
    a.style.display = 'none';
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
}
